mapper.select:
SELECT dhv.* FROM device_health_value dhv JOIN (
SELECT t1.device_id, t1.create_time, t1.health_value, t1.id FROM device_health_value t1 INNER JOIN ( SELECT t2.device_id, max( t2.create_time ) AS create_time,t2.id FROM device_health_value t2 where device_id in
#{id}
GROUP BY t2.device_id ) AS t3 ON t1.device_id = t3.device_id AND t1.create_time = t3.create_time GROUP BY t1.device_id
) t ON dhv.id = t.id
